function legoProcess(data,w,h,opts){
  opts=opts||{};
  var cell=opts.cell!=null?opts.cell:14;
  if(cell<6)cell=6; else if(cell>40)cell=40;
  var out=new Uint8ClampedArray(data.length);
  for(var i=0;i<out.length;i+=4){ out[i]=18; out[i+1]=18; out[i+2]=22; out[i+3]=255; }
  for(var gy=0;gy<h;gy+=cell) for(var gx=0;gx<w;gx+=cell){
    var cw=Math.min(cell,w-gx), ch=Math.min(cell,h-gy);
    var sr=0,sg=0,sb=0,n=0;
    for(var yy=gy;yy<gy+ch;yy++) for(var xx=gx;xx<gx+cw;xx++){ var p=(yy*w+xx)*4; sr+=data[p]; sg+=data[p+1]; sb+=data[p+2]; n++; }
    var r=Math.round(sr/n), g=Math.round(sg/n), b=Math.round(sb/n);
    for(var py=gy;py<gy+ch;py++) for(var px=gx;px<gx+cw;px++){
      var pp=(py*w+px)*4;
      out[pp]=r; out[pp+1]=g; out[pp+2]=b;
      // brick edge bevel
      if(px===gx||py===gy){ out[pp]=r*1.25+30; out[pp+1]=g*1.25+30; out[pp+2]=b*1.25+30; }
      if(px===gx+cw-1||py===gy+ch-1){ out[pp]=r*0.6; out[pp+1]=g*0.6; out[pp+2]=b*0.6; }
      // stud
      var cx=gx+cw/2, cy=gy+ch/2, rad=cw*0.26;
      var dx=px-cx, dy=py-cy;
      if(dx*dx+dy*dy<=rad*rad){ out[pp]=Math.min(255,r*1.35+45); out[pp+1]=Math.min(255,g*1.35+45); out[pp+2]=Math.min(255,b*1.35+45); }
    }
  }
  return out;
}

var EXPORTS={legoProcess:legoProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LegoForgePure = EXPORTS; }
